	@Test
	void smokeBothSparseProducers(@TempDir Path directory) {
		for (Shape shape : Shape.values()) {
			try (Fixture fixture = new Fixture(directory.resolve(shape.name()), shape)) {
				String query = shape.query("(COUNT(*) AS ?count)", "", "");
				Map<Map<String, Value>, Integer> expected = fixture.rows(query, false, false);
				assertFalse(expected.isEmpty(), query);
				assertEquals(expected, fixture.rows(query, true, false), query);
				assertEquals(expected, fixture.rows(query, true, true), query);
				Observation observation = fixture.explain(query, true);
				assertTrue(observation.sparse(), () -> shape + ": " + observation);
				assertTrue(observation.plans().stream().anyMatch(plan -> plan.contains(shape.planMarker)),
						() -> shape + ": " + observation);
			}
		}
	}

	@Test
	void everyOrderedAggregatePairKeepsItsRouteAndBag(@TempDir Path directory) {
		for (Shape shape : Shape.values()) {
			int eligible = 0;
			int rejected = 0;
			int forcedBypassed = 0;
			int automaticSparse = 0;
			try (Fixture fixture = new Fixture(directory.resolve(shape.name()), shape)) {
				for (Aggregate left : AGGREGATES) {
					for (Aggregate right : AGGREGATES) {
						String label = shape + ": " + left.name + ", " + right.name;
						String select = "(" + left.expression + " AS ?x) (" + right.expression + " AS ?y)";
						String query = shape.query(select, "", "");
						Map<Map<String, Value>, Integer> expected = fixture.rows(query, false, false);
						assertFalse(expected.isEmpty(), label);
						assertEquals(expected, fixture.rows(query, true, false), label);
						Observation automatic = fixture.explain(query, false);
						if (automatic.sparse()) {
							automaticSparse++;
						}
						if (left.eligible && right.eligible) {
							eligible++;
							assertEquals(expected, fixture.rows(query, true, true), label);
							Observation forced = fixture.explain(query, true);
							assertTrue(forced.sparse(), () -> label + ": " + forced);
							assertTrue(forced.plans().stream().anyMatch(plan -> plan.contains(shape.planMarker)),
									() -> label + ": " + forced);
						} else {
							rejected++;
							assertFalse(automatic.sparse(), () -> label + ": " + automatic);
							try {
								Map<Map<String, Value>, Integer> forced = fixture.rows(query, true, true);
								assertEquals(expected, forced, label);
								assertFalse(fixture.explain(query, true).sparse(), label);
								forcedBypassed++;
							} catch (QueryEvaluationException expectedDecline) {
								assertTrue(expectedDecline.getMessage().contains("could not be forced"),
										() -> label + ": " + expectedDecline);
							}
						}
					}
				}
			}
			System.out.println("SPARSE_MATRIX_PAIRS " + shape + " total=" + (eligible + rejected)
					+ " forcedSparse=" + eligible + " notSparse=" + rejected + " forcedBypassed=" + forcedBypassed
					+ " automaticSparse=" + automaticSparse);
		}
	}

