	@Test
	void invalidConstantRegexOnFixedPredicate(@TempDir Path directory) {
		checkInvalidConstantRegex(directory, Shape.FIXED);
	}

	@Test
	void invalidConstantRegexOnProjectedPredicate(@TempDir Path directory) {
		checkInvalidConstantRegex(directory, Shape.PREDICATE);
	}

	private static void checkInvalidConstantRegex(Path directory, Shape shape) {
		try (Fixture fixture = new Fixture(directory, shape)) {
			String query = shape.query("(COUNT(*) AS ?n)", "FILTER(REGEX(STR(?a), '['))", "");
			RegexResult generic = regexResult(fixture, query, false, false);
			RegexResult automatic = regexResult(fixture, query, true, false);
			RegexResult forced = regexResult(fixture, query, true, true);
			System.out.println("SPARSE_MATRIX_REGEX_ERROR shape=" + shape + " generic=" + generic
					+ " automatic=" + automatic + " forced=" + forced);
			assertAll(
					() -> assertNull(automatic.error, "automatic FILTER expression error should eliminate solutions"),
					() -> {
						if (automatic.error == null) {
							assertTrue(automatic.rows.isEmpty(), "automatic invalid regex result");
						}
					},
					() -> {
						if (forced.error == null) {
							assertTrue(forced.rows.isEmpty(), "forced invalid regex result");
							assertTrue(forced.observation.sparse(), () -> "Expected executed sparse route: "
									+ forced.observation);
						} else {
							assertTrue(forced.error instanceof QueryEvaluationException
									&& forced.error.getMessage().contains("could not be forced"),
									forced.error.toString());
						}
					});
		}
	}

	private static RegexResult regexResult(Fixture fixture, String query, boolean nativeEnabled, boolean forced) {
		try {
			Map<Map<String, Value>, Integer> rows = fixture.rows(query, nativeEnabled, forced);
			Observation observation = nativeEnabled ? fixture.explain(query, forced) : null;
			return new RegexResult(rows, null, observation);
		} catch (RuntimeException error) {
			return new RegexResult(null, error, null);
		}
	}

