	@Test
	void overriddenBuiltinFamiliesRespectResolvedImplementation(@TempDir Path directory) {
		Value replacement = SimpleValueFactory.getInstance().createLiteral(777);
		String timestamp = "xsd:dateTime(CONCAT('2024-01-01T00:00:00', "
				+ "IF(STR(?a) = '', '', 'Z')))";
		List<OverrideSpec> cases = List.of(
				new OverrideSpec("strlen", FN.STRING_LENGTH.stringValue(), "STRLEN(STR(?a))", false),
				new OverrideSpec("abs", FN.NUMERIC_ABS.stringValue(), "ABS(STRLEN(STR(?a)))", false),
				new OverrideSpec("starts", FN.STARTS_WITH.stringValue(), "STRSTARTS(STR(?a), 'none')", false),
				new OverrideSpec("ends", FN.ENDS_WITH.stringValue(), "STRENDS(STR(?a), 'none')", false),
				new OverrideSpec("contains", FN.CONTAINS.stringValue(), "CONTAINS(STR(?a), 'none')", false),
				new OverrideSpec("lower", FN.LOWER_CASE.stringValue(), "LCASE(STR(?a))", false),
				new OverrideSpec("upper", FN.UPPER_CASE.stringValue(), "UCASE(STR(?a))", false),
				new OverrideSpec("replace", FN.REPLACE.stringValue(), "REPLACE(STR(?a), 'x', 'y')", false),
				new OverrideSpec("year", FN.YEAR_FROM_DATETIME.stringValue(), "YEAR(" + timestamp + ")", false),
				new OverrideSpec("md5", new MD5().getURI(), "MD5(STR(?a))", false),
				new OverrideSpec("integer", XSD.INTEGER.stringValue(), "xsd:integer(STRLEN(STR(?a)))", false),
				new OverrideSpec("triple", new StatementFunction().getURI(),
						"<" + new StatementFunction().getURI() + ">(?a, ex:p, ?b)", false),
				new OverrideSpec("now", "NOW", "NOW()", true),
				new OverrideSpec("rand", "RAND", "RAND()", true));
		List<Executable> shapes = new ArrayList<>();
		for (Shape shape : Shape.values()) {
			shapes.add(() -> {
				try (Fixture fixture = new Fixture(directory.resolve(shape.name()), shape)) {
					List<Executable> checks = new ArrayList<>();
					for (OverrideSpec test : cases) {
						checks.add(() -> checkReplacedFamily(fixture, shape, test, replacement));
					}
					assertAll(shape.toString(), checks);
				}
			});
		}
		assertAll(shapes);
	}

	private static void checkReplacedFamily(Fixture fixture, Shape shape, OverrideSpec test, Value value) {
		Function replacement = new Function() {
			@Override
			public String getURI() {
				return test.uri;
			}

			@Override
			public Value evaluate(ValueFactory valueFactory, Value... args) {
				return value;
			}

			@Override
			public Determinism getDeterminism() {
				return test.volatileFunction ? Determinism.VOLATILE : Determinism.DETERMINISTIC;
			}
		};
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.add(replacement).orElse(null);
		try {
			String projection = shape.query("(" + test.expression + " AS ?value) (COUNT(*) AS ?n)", "", "");
			String filter = shape.query("(COUNT(*) AS ?n)", "FILTER(STR(" + test.expression + ") = '777')", "");
			assertAll(test.name,
					() -> assertOverrideParity(fixture, projection, test.name + " projection"),
					() -> assertOverrideParity(fixture, filter, test.name + " endpoint filter"));
		} finally {
			registry.remove(replacement);
			if (previous != null) {
				registry.add(previous);
			}
		}
	}

	private static void assertOverrideParity(Fixture fixture, String query, String label) {
		Map<Map<String, Value>, Integer> generic = fixture.rows(query, false, false);
		assertFalse(generic.isEmpty(), label + " must exercise the replacement");
		Map<Map<String, Value>, Integer> automatic = fixture.rows(query, true, false);
		Map<Map<String, Value>, Integer> forced = null;
		try {
			forced = fixture.rows(query, true, true);
		} catch (QueryEvaluationException declined) {
			assertTrue(declined.getMessage().contains("could not be forced"), declined.toString());
		}
		Map<Map<String, Value>, Integer> forcedResult = forced;
		assertAll(label,
				() -> assertEquals(generic, automatic, label + " automatic"),
				() -> {
					if (forcedResult != null) {
						assertEquals(generic, forcedResult, label + " forced");
					}
				});
	}

	@Test
	void overrideCannotBorrowBuiltinMetadataOrCacheIdentity() {
		FunctionRegistry registry = FunctionRegistry.getInstance();
		FunctionCall plain = new FunctionCall(FN.STRING_LENGTH.stringValue(), new Var("value"));
		FunctionCall pinned = QueryEvaluationUtility.pinFunctions(plain.clone());
		NativeScalarPlan original = NativeScalarPlan.create(pinned, name -> 0, NativeScalarPlan.ResultKind.NUMERIC,
				false, 1L, false, false);
		FunctionCall constant = new FunctionCall(FN.STRING_LENGTH.stringValue(),
				new ValueConstant(SimpleValueFactory.getInstance().createLiteral("abc")));
		NativeScalarPlan retained = NativeScalarPlan.create(constant, name -> -1, NativeScalarPlan.ResultKind.NUMERIC,
				false, 0L, false, false);
		assertNotNull(original);
		assertNotNull(retained);
		Function replacement = new StrLen() {
			@Override
			public Literal evaluate(ValueFactory vf, Value... args) {
				return vf.createLiteral(777);
			}

			@Override
			public Determinism getDeterminism() {
				return Determinism.VOLATILE;
			}
		};
		Function previous = registry.add(replacement).orElse(null);
		try {
			NativeScalarPlan custom = NativeScalarPlan.create(plain, name -> 0, NativeScalarPlan.ResultKind.NUMERIC,
					false, 1L, false, false);
			NativeScalarPlan stillPinned = NativeScalarPlan.create(pinned, name -> 0,
					NativeScalarPlan.ResultKind.NUMERIC, false, 1L, false, false);
			assertNotNull(custom);
			assertNotNull(stillPinned);
			assertAll(
					() -> assertEquals(EffectClass.SIDE_EFFECTING_OR_UNSUPPORTED, custom.effect()),
					() -> assertEquals(-1, custom.lexicalLengthInputSlot()),
					() -> assertFalse(NativeScalarResultDomain.exactNumeric(plain)),
					() -> assertNotEquals(original, custom),
					() -> assertEquals(EffectClass.PURE, stillPinned.effect()),
					() -> assertEquals(0, stillPinned.lexicalLengthInputSlot()),
					() -> assertTrue(NativeScalarResultDomain.exactNumeric(pinned)));
			NativeScalarPlan.WorkerContext worker = new NativeScalarPlan.WorkerContext(
					mock(NativeLmdbQuerySource.class),
					mock(LmdbNativeValueCodec.class), null);
			LmdbNativeCompiledNumeric rebound = retained.bindNumeric(worker);
			assertNotNull(rebound, "a worker must retain the pinned built-in after replacement");
			assertEquals(3, rebound.evaluator.eval(mock(LmdbNativeSlotReader.class)).decimal.intValueExact());
			registry.remove(replacement);
			assertNull(LmdbNativeFunctionLibrary.entry(plain), "a missing registration has no native proof");
			assertNotNull(LmdbNativeFunctionLibrary.entry(pinned),
					"the earlier pinned call retains its implementation");
			registry.add(new StrLen());
			assertNotNull(LmdbNativeFunctionLibrary.entry(plain), "an independent genuine built-in remains native");
		} finally {
			registry.remove(replacement);
			if (previous != null) {
				registry.add(previous);
			}
		}
	}

	@Test
	void everyAvailableNativeBuiltinRequiresItsResolvedImplementation() {
		FunctionRegistry registry = FunctionRegistry.getInstance();
		List<Function> originals = List.copyOf(registry.getAll());
		int checked = 0;
		for (Function builtin : originals) {
			LmdbNativeFunctionLibrary.Entry expected = LmdbNativeFunctionLibrary.entry(builtin.getURI());
			if (expected == null) {
				continue;
			}
			FunctionCall call = new FunctionCall(builtin.getURI());
			assertSame(expected, LmdbNativeFunctionLibrary.entry(call), builtin.getURI());
			Function custom = replacement(builtin.getURI(), "replacement");
			Function previous = registry.add(custom).orElse(null);
			try {
				assertNull(LmdbNativeFunctionLibrary.entry(call), builtin.getURI() + " replacement");
				registry.remove(custom);
				assertNull(LmdbNativeFunctionLibrary.entry(call), builtin.getURI() + " removal");
			} finally {
				registry.remove(custom);
				if (previous != null) {
					registry.add(previous);
				}
			}
			assertSame(expected, LmdbNativeFunctionLibrary.entry(call), builtin.getURI() + " restoration");
			checked++;
		}
		assertTrue(checked >= 45, "the native function catalogue must retain its healthy built-in entries");
		System.out.println("NATIVE_BUILTIN_IDENTITY_ENTRIES " + checked);
	}

