	private static void checkCustomOrderHint(Path directory, String uri) {
		OrderByHint hint = new OrderByHint() {
			@Override
			public String getURI() {
				return uri;
			}

			@Override
			public String getUnsupportedOrderByMessage() {
				return "custom ordering hint is unsupported";
			}

			@Override
			public Value evaluate(ValueFactory vf, Value... args) {
				return vf.createLiteral(1);
			}
		};
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.add(hint).orElse(null);
		try (Fixture fixture = new Fixture(directory, Shape.FIXED)) {
			String query = PREFIX + "SELECT ?a WHERE { ?a ex:p ?j } ORDER BY <" + uri + ">(?a)";
			QueryEvaluationException generic = assertThrows(QueryEvaluationException.class,
					() -> orderedRows(fixture.repository, query, false));
			assertTrue(generic.getMessage().contains("custom ordering hint is unsupported"));
			QueryEvaluationException nativeFailure = assertThrows(QueryEvaluationException.class,
					() -> orderedRows(fixture.repository, query, true));
			assertTrue(nativeFailure.getMessage().contains("custom ordering hint is unsupported"));
		} finally {
			registry.remove(hint);
			if (previous != null) {
				registry.add(previous);
			}
		}
	}

	private static List<String> orderedRows(SailRepository repository, String text, boolean nativeEnabled) {
		String previous = System.setProperty(NATIVE_PROPERTY, Boolean.toString(nativeEnabled));
		try (var connection = repository.getConnection()) {
			List<String> rows = new ArrayList<>();
			try (var result = connection.prepareTupleQuery(text).evaluate()) {
				while (result.hasNext()) {
					rows.add(result.next().getValue("a").stringValue());
				}
			}
			return rows;
		} finally {
			restoreProperty(NATIVE_PROPERTY, previous);
		}
	}

